assertApiContractShape(API_CONTRACT)

export function projectComponentExports(componentId: string): ComponentExportProjection {
    return projectSharedComponentExports(API_CONTRACT, componentId)
}

export function getApiEntry(entryId: string): ApiEntryContract {
    const entry = API_CONTRACT.entries.find((candidate) => candidate.id === entryId)
    if (!entry) throw new Error(`API contract has no entry '${entryId}'`)
    return entry
}

